"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useTheme } from "@/components/theme-provider";
import { MODULE_NOTIFICATIONS } from "@/lib/notifications";

const navItems = [
  { href: "/", label: "Dashboard" },
  { href: "/stock", label: "Stock" },
  { href: "/attendance", label: "Attendance" },
  { href: "/compliance", label: "Compliance" },
];

export function Sidebar() {
  const pathname = usePathname();
  const { theme, toggleTheme } = useTheme();

  return (
    <aside className="fixed inset-y-0 left-0 z-40 w-64 border-r border-[var(--border)] bg-[var(--panel)] text-[var(--text)] transition-colors duration-300">
      <div className="flex h-16 items-center justify-between px-6">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-cyan-400 to-blue-600 flex items-center justify-center text-white font-bold">
            Y
          </div>
          <span className="font-bold text-xl tracking-tight">Yogya</span>
        </div>
        <button
          onClick={toggleTheme}
          className="p-2 rounded-md hover:bg-[var(--hover)] transition-colors"
          aria-label="Toggle theme"
        >
          {theme === "light" ? "🌙" : "☀️"}
        </button>
      </div>

      <nav className="mt-6 px-3 space-y-1">
        {navItems.map((item) => {
          const active = pathname === item.href;
          const notif = MODULE_NOTIFICATIONS[item.href];
          const pending = notif ? notif.pending : 0;

          return (
            <Link
              key={item.href}
              href={item.href}
              className={`flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-colors ${
                active
                  ? "bg-[var(--accent)] text-white shadow-[0_0_15px_rgba(34,211,238,0.4)]"
                  : "hover:bg-[var(--hover)] text-[var(--text-muted)]"
              }`}
            >
              {item.label}
              {pending > 0 && (
                <span className="ml-auto flex items-center gap-1.5">
                  <span
                    className="w-2 h-2 rounded-full bg-red-500 shadow-[0_0_8px_#ef4444] animate-pulse"
                    aria-hidden="true"
                  ></span>
                  <span className="text-[10px] font-bold text-red-500">{pending}</span>
                </span>
              )}
            </Link>
          );
        })}
      </nav>

      <div className="absolute bottom-0 left-0 w-full p-6 border-t border-[var(--border)]">
        <div className="text-xs text-[var(--text-muted)] mb-4">v1.0.0</div>
        <button
          onClick={toggleTheme}
          className="w-full px-4 py-3 rounded-xl bg-[var(--hover)] text-[var(--text)] text-sm font-medium hover:bg-[var(--accent)] hover:text-white transition-colors"
        >
          {theme === "light" ? "Switch to Dark Mode" : "Switch to Light Mode"}
        </button>
      </div>
    </aside>
  );
}
